def attrs(fill=BLUE,stroke=INK,w=5):return f'fill="{fill}" stroke="{stroke}" stroke-width="{w}" stroke-linecap="round" stroke-linejoin="round"'
def r(x,y,w,h,fill=BLUE,rx=10,stroke=INK):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" {attrs(fill,stroke)}/>'
def c(x,y,rr,fill=BLUE,stroke=INK,w=5):return f'<circle cx="{x}" cy="{y}" r="{rr}" {attrs(fill,stroke,w)}/>'
def e(x,y,rx,ry,fill=BLUE):return f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" {attrs(fill)}/>'
def p(d,fill='none',stroke=INK,w=5):return f'<path d="{d}" {attrs(fill,stroke,w)}/>'
def l(x1,y1,x2,y2,stroke=INK,w=5):return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" {attrs("none",stroke,w)}/>'
def poly(points,fill=BLUE):return f'<polygon points="{points}" {attrs(fill)}/>'
def cross(x=128,y=128,s=30,fill=WHITE):return p(f'M{x-s/3} {y-s} H{x+s/3} V{y-s/3} H{x+s} V{y+s/3} H{x+s/3} V{y+s} H{x-s/3} V{y+s/3} H{x-s} V{y-s/3} H{x-s/3} Z',fill)
def check(x=128,y=128,s=28):return p(f'M{x-s} {y} l{.65*s} {.65*s} l{1.35*s} {-1.4*s}',stroke=INK,w=7)
def rows(x=75,y=100,n=4,length=100,step=22):return ''.join(l(x,y+k*step,x+length-(k%2)*22,y+k*step) for k in range(n))
def rays(cx,cy,n=8,r1=60,r2=78):return ''.join(l(round(cx+math.cos(k*math.tau/n)*r1,2),round(cy+math.sin(k*math.tau/n)*r1,2),round(cx+math.cos(k*math.tau/n)*r2,2),round(cy+math.sin(k*math.tau/n)*r2,2)) for k in range(n))
