def build():
 import xml.etree.ElementTree as ET
 index=[]
 for cat,category,fn,names in CATEGORIES:
  assert len(names)==20
  for i,title in enumerate(names):
   sid=f'SV{len(index)+1:04d}'; art=fn(i)
   # Three actual SVG child groups provide lightweight motion-layer targets.
   fragments=list(ET.fromstring('<g>'+art+'</g>'))
   a=max(1,len(fragments)//3); b=max(a+1,2*len(fragments)//3)
   parts=[fragments[:a],fragments[a:b],fragments[b:]]
   grouped=''.join(f'<g id="{name}">'+''.join(ET.tostring(v,encoding='unicode') for v in fragment)+'</g>' for name,fragment in zip(('main','accent','details'),parts))
   svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" width="256" height="256" role="img" aria-labelledby="title desc"><title id="title">{html.escape(title)}</title><desc id="desc">Original pastel outlined vector illustration of {html.escape(title.lower())}, with separately addressable main, accent and details groups.</desc>{grouped}</svg>'
   (OUT/f'{sid}.svg').write_text(svg)
   index.append({'id':sid,'title':title,'category':category,'category_slug':cat,'tags':[cat,'pastel','outlined','layered','original',title.lower()],'svg':f'svg/files/{sid}.svg','viewBox':'0 0 256 256','license':'Original generated SVG; reusable','layers':['main','accent','details']})
 assert len(index)==500
 (ROOT/'svg_icons_index.json').write_text(json.dumps(index,indent=2))
 print(f'Created {len(index)} SVG assets and {len(CATEGORIES)} categories in {OUT}')

def qa():
 import xml.etree.ElementTree as ET, hashlib,re
 import cairosvg
 from PIL import Image,ImageDraw,ImageFont
 index=json.loads((ROOT/'svg_icons_index.json').read_text()); hashes=set(); structural_hashes=set();edge=[]
 qa_dir=ROOT/'qa/icons';qa_dir.mkdir(parents=True,exist_ok=True)
 for item in index:
  f=OUT/f'{item["id"]}.svg';s=f.read_text();ET.fromstring(s)
  assert '<script' not in s and 'href=' not in s and '<image' not in s
  h=hashlib.sha256(s[s.index('<g'):].encode()).hexdigest();assert h not in hashes;hashes.add(h)
  geometry=re.sub(r' (?:fill|stroke)="[^"]*"','',s[s.index('<g'):])
  structural_hashes.add(hashlib.sha256(geometry.encode()).hexdigest())
  dest=qa_dir/f'{item["id"]}.png';cairosvg.svg2png(url=str(f),write_to=str(dest),output_width=128,output_height=128)
  im=Image.open(dest).convert('RGBA');assert im.getbbox(),item['id']
  alpha=im.getchannel('A');assert alpha.getextrema()[0]==0,item['id']
  if any(alpha.getpixel((x,y)) for x,y in [(x,0) for x in range(128)]+[(x,127) for x in range(128)]+[(0,y) for y in range(128)]+[(127,y) for y in range(128)]):edge.append(item['id'])
 for cat,category,fn,names in CATEGORIES:
  sheet=Image.new('RGB',(900,760),'#F2F5F8');d=ImageDraw.Draw(sheet);d.text((20,10),category,fill=INK)
  items=[x for x in index if x['category_slug']==cat]
  for k,it in enumerate(items):
   x=20+(k%5)*176;y=42+(k//5)*177
   im=Image.open(qa_dir/f'{it["id"]}.png');sheet.paste(im,(x+21,y),im)
   d.text((x,y+131),it['id']+' '+it['title'][:24],fill=INK)
  sheet.save(ROOT/f'qa/contact_{cat}.jpg',quality=88)
 overview=Image.new('RGB',(2250,1900),'white')
 for k,(cat,category,fn,names) in enumerate(CATEGORIES):
  thumb=Image.open(ROOT/f'qa/contact_{cat}.jpg');thumb.thumbnail((450,380));overview.paste(thumb,((k%5)*450,(k//5)*380))
 overview.save(ROOT/'qa/svg_icons_500_overview.jpg',quality=91)
 assert len(structural_hashes)==500
 assert not edge,edge
 summary={'count':len(index),'categories':len(CATEGORIES),'valid_xml':500,'raster_rendered':500,'unique_geometry_hashes':len(hashes),'geometry_hashes_ignoring_colours':len(structural_hashes),'edge_clipped_rasters':edge,'transparent':500,'no_scripts_external_refs_embedded_images':True,'size':'256x256 viewBox','contact_sheets':25,'overview':'qa/svg_icons_500_overview.jpg'}
 (ROOT/'svg_icons_qa.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary))
if __name__=='__main__':
 import sys
 build()
 if '--qa' in sys.argv:qa()
